using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    for (int i = 1; i <= n; ++i) {
        sort(adj[i].begin(), adj[i].end());
    }

    vector<vector<int>> val(n + 1);
    for (int i = 1; i <= n; ++i) {
        val[i].assign(adj[i].size(), 0);
    }

    vector<int> curMax(n + 1, 0);

    for (int v = n; v >= 1; --v) {
        auto &neigh = adj[v];
        auto &vvals = val[v];
        int d = (int)neigh.size();

        for (int i = 0; i < d; ++i) {
            int w = neigh[i];
            if (w < v) {
                vvals[i] = 1 + curMax[w];
            }
        }

        int suffix = 0;
        for (int i = d - 1; i >= 0; --i) {
            int w = neigh[i];

            if (w < v) {
                int dp_w_v = 1 + suffix;

                auto &adjw = adj[w];
                int pos = lower_bound(adjw.begin(), adjw.end(), v) - adjw.begin();
                val[w][pos] = dp_w_v;

                if (dp_w_v > curMax[w]) {
                    curMax[w] = dp_w_v;
                }
            }

            if (vvals[i] > suffix) {
                suffix = vvals[i];
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        int best = 0;
        for (int x : val[i]) {
            if (x > best) best = x;
        }

        int ans = (best == 0 ? 1 : best + 1);
        if (i > 1) cout << ' ';
        cout << ans;
    }
    cout << '\n';

    return 0;
}
